//   seam=none; no_claim=provider usage shape (hand-written usage objects; unit only)
// Value: protects=a stream that ends before its final usage is charged the request's worst case;
//   fails_when=finish() bills partial usage when stop_reason never arrives; why_new=existing tests cover close and
//   cancel, not a truncated stream; seam=none; no_claim=real provider streams (local stub upstream)
// Value: protects=forward routes bound input with count_tokens plus slack and fall back to the byte bound when
//   counting fails, and a failed count whose byte bound passes the cap answers a retryable 529, not a budget stop;
//   fails_when=the count is ignored, a failed count admits a request on a guess, or it ends the trial as a budget stop;
//   why_new=runner.test.ts uses estimate routes only; seam=none; no_claim=Anthropic count_tokens accuracy (stub)
// Value: protects=the global cap refuses a session whose full reserve does not fit, latches the cap stop and blocks
//   new sessions;
//   fails_when=the global check or the latch is removed; why_new=no existing test sets globalCapMicros;
//   seam=none; no_claim=ledger interaction (no ledger URL in this proxy)
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { costMicros, emptyUsage, mergeUsage, startProxy, worstCaseMicros, COUNT_SLACK_TOKENS, type ProxyConfig } from "../runner/proxy.ts";

const dir = mkdtempSync(join(tmpdir(), "laneb-acct-"));
const price = { input: 5, output: 25, cache_write_5m: 6.25, cache_write_1h: 10, cache_read: 0.5 };
const readLog = (name: string) => readFileSync(join(dir, name), "utf8").trim().split("\n").map((l) => JSON.parse(l));

test("cache_creation splits into 5m and 1h writes, and the 1h part bills at the 1h rate", () => {
  const derived = emptyUsage();
  mergeUsage(derived, { input_tokens: 10, output_tokens: 20, cache_creation_input_tokens: 1000, cache_creation: { ephemeral_1h_input_tokens: 400 } });
  expect(derived).toEqual({ input_tokens: 10, output_tokens: 20, cache_creation_input_tokens: 600, cache_creation_1h_input_tokens: 400, cache_read_input_tokens: 0 });
  const explicit = emptyUsage();
  mergeUsage(explicit, { cache_creation_input_tokens: 1000, cache_creation: { ephemeral_5m_input_tokens: 250, ephemeral_1h_input_tokens: 750 } });
  expect(explicit.cache_creation_input_tokens).toBe(250);
  expect(explicit.cache_creation_1h_input_tokens).toBe(750);
  expect(costMicros(explicit, price)).toBe(Math.ceil(250 * 6.25 + 750 * 10));
});

describe("proxy accounting against a stub upstream", () => {
  let countFails = 0;
  let countValue = 10;
  let messagesSeen = 0;
  const enc = new TextEncoder();
  const ev = (type: string, data: unknown) => enc.encode(`event: ${type}\ndata: ${JSON.stringify(data)}\n\n`);
  let upstream: ReturnType<typeof Bun.serve>;
  let estimate: ReturnType<typeof startProxy>;
  let forward: ReturnType<typeof startProxy>;
  let capped: ReturnType<typeof startProxy>;

  beforeAll(() => {
    upstream = Bun.serve({
      hostname: "127.0.0.1",
      port: 0,
      async fetch(req) {
        const url = new URL(req.url);
        const body = (await req.json()) as any;
        if (url.pathname.endsWith("/count_tokens")) {
          if (countFails > 0) {
            countFails--;
            return Response.json({ type: "error", error: { type: "api_error", message: "count down" } }, { status: 500 });
          }
          return Response.json({ input_tokens: countValue });
        }
        messagesSeen++;
        const truncated = Boolean(body.metadata?.truncated);
        const stream = new ReadableStream<Uint8Array>({
          start(ctrl) {
            ctrl.enqueue(ev("message_start", { type: "message_start", message: { usage: { input_tokens: 100, output_tokens: 1 } } }));
            if (!truncated) {
              ctrl.enqueue(ev("message_delta", { type: "message_delta", delta: { stop_reason: "end_turn" }, usage: { output_tokens: 50 } }));
              ctrl.enqueue(ev("message_stop", { type: "message_stop" }));
            }
            ctrl.close();
          },
        });
        return new Response(stream, { headers: { "content-type": "text/event-stream" } });
      },
    });
    const route = (count_tokens: "estimate" | "forward") => ({ base_url: `http://127.0.0.1:${upstream.port}`, key_env: "FAKE_KEY", auth: "x-api-key" as const, count_tokens });
    const config = (count_tokens: "estimate" | "forward"): ProxyConfig => ({ routes: { stub: route(count_tokens) }, models: { m: { route: "stub", upstream_model: "m-up", price_per_mtok: price } } });
    const base = { dataHost: "127.0.0.1", dataPort: 0, controlPort: 0, env: { FAKE_KEY: "fake" }, closeWaitMs: 300 };
    estimate = startProxy({ ...base, config: config("estimate"), logPath: join(dir, "est.jsonl"), sessionsPath: join(dir, "est-s.jsonl") });
    forward = startProxy({ ...base, config: config("forward"), logPath: join(dir, "fwd.jsonl"), sessionsPath: join(dir, "fwd-s.jsonl") });
    capped = startProxy({ ...base, config: config("estimate"), logPath: join(dir, "cap.jsonl"), sessionsPath: join(dir, "cap-s.jsonl"), globalCapMicros: 20_000 });
  });
  afterAll(async () => {
    await estimate.stop();
    await forward.stop();
    await capped.stop();
    upstream.stop(true);
    rmSync(dir, { recursive: true, force: true });
  });

  const control = (p: ReturnType<typeof startProxy>) => `http://127.0.0.1:${p.control.port}`;
  const open = (p: ReturnType<typeof startProxy>, cap: number) => fetch(control(p) + "/sessions", { method: "POST", body: JSON.stringify({ trial: "t", model: "m", cap_usd: cap }) });
  const message = (p: ReturnType<typeof startProxy>, token: string, extra: Record<string, unknown> = {}) =>
    fetch(`http://127.0.0.1:${p.data.port}/v1/messages`, { method: "POST", headers: { "x-api-key": token, "content-type": "application/json" }, body: JSON.stringify({ model: "x", max_tokens: 1000, stream: true, messages: [{ role: "user", content: "hi" }], ...extra }) });
  const close = async (p: ReturnType<typeof startProxy>, id: string) => (await (await fetch(control(p) + `/sessions/${id}/close`, { method: "POST", body: "{}" })).json()) as any;

  test("a stream that ends without its final usage is charged the worst case", async () => {
    const s = (await (await open(estimate, 1)).json()) as any;
    const res = await message(estimate, s.token, { metadata: { truncated: true } });
    expect(res.status).toBe(200);
    await res.text();
    const closed = await close(estimate, s.id);
    const entry = readLog("est.jsonl").find((e) => e.event === "request" && e.session === s.id);
    expect(entry.complete).toBe(false);
    expect(entry.cost_micros).toBe(entry.worst_micros);
    expect(closed.spent_micros).toBe(entry.worst_micros);
    expect(closed.spent_micros).toBeGreaterThan(costMicros({ ...emptyUsage(), input_tokens: 100, output_tokens: 1 }, price));
  });

  test("count_tokens bounds input on forward routes, and a failed count falls back to the byte bound", async () => {
    const counted = worstCaseMicros(10 + COUNT_SLACK_TOKENS, 1000, price, false);
    expect(counted).toBeLessThan(30_000);
    const a = (await (await open(forward, 0.03)).json()) as any;
    const ok = await message(forward, a.token);
    expect(ok.status).toBe(200);
    await ok.text();
    await close(forward, a.id);
    const entry = readLog("fwd.jsonl").find((e) => e.event === "request" && e.session === a.id);
    expect(entry).toMatchObject({ counted: true, input_tokens_bound: 10 + COUNT_SLACK_TOKENS, worst_micros: counted, complete: true });

    // The same request with a failed count: its byte bound passes the cap, so it gets a retryable 529 and no upstream
    // call; the retry is counted, fits, and runs.
    countFails = 1;
    const b = (await (await open(forward, 0.03)).json()) as any;
    const before = messagesSeen;
    const retry = await message(forward, b.token);
    expect(retry.status).toBe(529);
    expect(((await retry.json()) as any).error).toEqual({ type: "overloaded_error", message: "laneb proxy: token count unavailable, retry" });
    expect(messagesSeen).toBe(before);
    const again = await message(forward, b.token);
    expect(again.status).toBe(200);
    await again.text();
    const closed = await close(forward, b.id);
    expect(closed).toMatchObject({ refused: 0, refused_budget: 0, requests: 1, ok_responses: 1 });
    const log = readLog("fwd.jsonl").filter((e) => e.session === b.id);
    expect(log.some((e) => e.event === "count_failed" && e.status === 500)).toBe(true);
    expect(log.find((e) => e.event === "count_failed_over_budget")).toMatchObject({ cap_micros: 30_000 });
    expect(log.some((e) => e.event === "refused")).toBe(false);

    // A counted request over the cap is still a budget stop.
    const c = (await (await open(forward, 0.02)).json()) as any;
    const over = await message(forward, c.token);
    expect(over.status).toBe(400);
    expect(await over.text()).toContain("session budget exhausted");
    expect(await close(forward, c.id)).toMatchObject({ refused_budget: 1 });
    expect(readLog("fwd.jsonl").find((e) => e.event === "refused" && e.session === c.id)).toMatchObject({ reason: "session_cap", counted: true });
  });

  test("a worst case that is not a positive number is refused before any upstream call", async () => {
    countValue = -1e9;
    const s = (await (await open(forward, 1)).json()) as any;
    const before = messagesSeen;
    const res = await message(forward, s.token);
    expect(res.status).toBe(400);
    expect(await res.text()).toContain("worst-case cost is not a positive number");
    expect(messagesSeen).toBe(before);
    expect(readLog("fwd.jsonl").find((e) => e.event === "refused" && e.session === s.id)).toMatchObject({ reason: "worst_case" });
    expect((await close(forward, s.id)).spent_micros).toBe(0);
    countValue = 10;
  });

  test("the global cap refuses a session that does not fit at open, latches the cap stop and blocks new sessions", async () => {
    const first = await open(capped, 1);
    expect(first.status).toBe(409);
    expect(((await first.json()) as any).error).toContain("batch cap reached");
    const totals = (await (await fetch(control(capped) + "/totals")).json()) as any;
    expect(totals.cap_stop).toContain("batch cap reached");
    expect(totals.global_spent_micros).toBe(0);
    expect(totals.sessions).toBe(0);
    const again = await open(capped, 0.001);
    expect(again.status).toBe(409);
    expect(((await again.json()) as any).error).toContain("budget stop latched");
  });
});
